create or replace function public.reapply_all_organization_plan_entitlements(p_reason text default 'Retroactive plan entitlement sync') returns jsonb language plpgsql security definer set search_path = public as $$ declare v_row record; v_count integer := 0; begin if not ( public.is_saas_admin() or coalesce(auth.jwt() ->> 'role', '') = 'service_role' or current_user in ('postgres', 'supabase_admin') ) then raise exception 'platform admin role required' using errcode = '42501'; end if; for v_row in select os.organization_id, os.plan_id from public.organization_subscriptions os where os.status in ('trial', 'active', 'past_due', 'suspended') loop perform public.apply_plan_entitlements( v_row.organization_id, v_row.plan_id, coalesce(nullif(trim(p_reason), ''), 'Retroactive plan entitlement sync') ); v_count := v_count + 1; end loop; if public.is_saas_admin() then perform public.record_platform_audit( 'entitlements.bulk_reapplied', null, 'organization', 'all', trim(p_reason), null, jsonb_build_object('organizations_synced', v_count) ); end if; return jsonb_build_object('organizations_synced', v_count); end; $$; revoke all on function public.reapply_all_organization_plan_entitlements(text) from public, anon; grant execute on function public.reapply_all_organization_plan_entitlements(text) to authenticated, service_role; select public.reapply_all_organization_plan_entitlements('V1.0 commercial edition entitlement sync');
